{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Verapamil, the closest analogue, has an absolute oral bioavailability of 34% in humans, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Noscapine, a structurally related dimethoxy-substituted isoquinoline, has an absolute oral bioavailability of 30% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Sulpiride, a related basic aromatic amide, is reported to have a bioavailability of 30% in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, another verapamil-like basic aromatic ether, shows 32 ± 7% absolute oral bioavailability in normal subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Alfentanil, a moderately lipophilic basic drug, has an oral bioavailability of 0.45 ± 0.09 in control subjects, supporting high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Levosulpiride, the enantiomer of sulpiride, shows about 30% oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "One verapamil study reports 19.4% bioavailability in young men, just below the 20% threshold, indicating a borderline first-pass liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a verapamil-like dimethoxy-substituted basic amine/lactam. The closest analogue verapamil has absolute oral bioavailability mostly 20-38%, and other structurally related analogues (noscapine, sulpiride, encainide, alfentanil, levosulpiride) all show F values of 23-45%. Although one verapamil study reports 19.4%, the weight of evidence supports F >= 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "First-pass metabolism and transporter effects specific to the lactam/tetrahydroisoquinoline motif are unknown.",
    "The chiral center may alter pharmacokinetics in a way not captured by the racemic or related analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

